import numpy as np
from scipy import stats
from sklearn.linear_model import LogisticRegression
from sklearn.model_selection import StratifiedKFold
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    if len(feats.ids) == 0:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Check if any mechanism exists by testing association within strata
    strata = list(set(feats.stratum))
    if len(strata) == 1:
        strata = ['all']

    # For each stratum, compute effect sizes
    stratum_effects = {}
    for s in strata:
        mask = np.array(feats.stratum) == s
        y_s = feats.y[mask]
        if len(y_s) < 2 or np.sum(y_s) == 0 or np.sum(y_s) == len(y_s):
            continue

        x_s = feats.x[mask]
        effects = []
        for i, fid in enumerate(feats.ids):
            if feats.types[i] in ('clinical', 'copy_number', 'expression'):
                corr = np.corrcoef(x_s[:,i], y_s)[0,1]
                effects.append((abs(corr), fid))

        if effects:
            effects.sort(reverse=True)
            stratum_effects[s] = [f for _, f in effects[:10]]  # Top 10

    # If no consistent pattern across strata, return empty design
    if not stratum_effects or len(stratum_effects) < len(strata)/2:
        return Design(drivers=(), columns=(), products=(), loadings={})

    # Get top features by effect size
    all_effects = defaultdict(list)
    for s, features in stratum_effects.items():
        for i, f in enumerate(features):
            all_effects[f].append(i)

    # Compute average rank across strata
    avg_ranks = [(np.mean(all_effects[f]), f) for f in all_effects]
    avg_ranks.sort()

    # Select top features
    selected_features = [f for _, f in avg_ranks[:MAX_DRIVERS]]

    # Remove near-duplicates
    filtered_features = []
    for f in selected_features:
        is_duplicate = False
        for existing in filtered_features:
            if f in feats.ids and existing in feats.ids:
                idx_f = feats.column(f)
                idx_e = feats.column(existing)
                if abs(np.corrcoef(feats.x[:,idx_f], feats.x[:,idx_e])[0,1]) > 0.6:
                    is_duplicate = True
                    break
        if not is_duplicate:
            filtered_features.append(f)

    # Build design
    drivers = tuple(filtered_features)
    columns = tuple(filtered_features)
    products = ()
    loadings = {fid: 1.0 for fid in filtered_features}

    return Design(drivers=drivers, columns=columns, products=products, loadings=loadings)

